function oneRandom(limit){const max=4294967296-4294967296%limit,n=new Uint32Array(1);do{crypto.getRandomValues(n);}while(n[0]>=max);return n[0]%limit;}
function onePackCards(pack){const counts=new Map();return Array.from({length:pack.count},()=>{let pick=oneRandom(100),rarity='normal';for(const [key,weight]of Object.entries(pack.chances)){if(pick<weight){rarity=key;break;}pick-=weight;}const pool=ONE_CARDS.filter(c=>c.rarity===rarity&&(counts.get(c.id)||0)<2);const id=pool[oneRandom(pool.length)].id;counts.set(id,(counts.get(id)||0)+1);return id;});}

